return [{ json: {
  run_id: 'wf4-' + $execution.id,
  started_at: new Date().toISOString()
}}];

const cfgRows = $('Read Config').all().map(i=>i.json).filter(r=>r.key);
const config = Object.fromEntries(cfgRows.map(r=>[r.key,String(r.value)]));
const rows = $('Read Calendar').all().map(i=>i.json).filter(r=>r.post_id && r.status==='published' && String(r.post_id).match(/^b\d+-p\d+$/));
if (!rows.length) throw new Error('No published posts to analyze yet - run WF3 first');
return rows.map(r=>({json:{...r,
  follower_base: config.follower_base||'12000',
  publish_mode: config.publish_mode||'dry_run',
  graph_api_version: config.graph_api_version||'v25.0',
  ig_access_token: config.ig_access_token||''
}}));

const r = $json;
function fnv(str){let h=0x811c9dc5;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,0x01000193)>>>0;}return h;}
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
const rng = mulberry32(fnv(String(r.post_id)));
function gauss(){ const u1 = Math.max(rng(), 1e-9), u2 = rng(); return Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2); }
const followers = parseInt(r.follower_base||'12000',10);
const fmt = String(r.format||'image').toLowerCase();
const formatReach = fmt==='reel'?0.45:(fmt==='carousel'?0.24:0.20);
let hour = 20;
try { hour = DateTime.fromISO(String(r.publish_at)).setZone('Africa/Cairo').hour; } catch(e) {}
const slotMult = hour>=21?1.25:(hour>=19?1.15:(hour>=15?1.0:0.9));
const p = String(r.pillar||'').toLowerCase();
const pillarAff = /book|offer|deal|promo|bliss/.test(p)?1.20:(/visual|escape|beauty|paradise/.test(p)?1.15:(/spa|wellness|seren|sanctuary/.test(p)?1.00:(/local|culture|charm/.test(p)?0.95:(/tip|guide|how/.test(p)?0.90:1.0))));
const capLen = String(r.caption_en||'').length;
let capMult = 1.0;
if (capLen>=80 && capLen<=300) capMult *= 1.05;
if (capLen>2200) capMult *= 0.95;
if (r.caption_ar && r.caption_en) capMult *= 1.05;
const noiseReach = 1 + 0.12*gauss();
const noiseEng = 1 + 0.12*gauss();
const reach = Math.max(200, Math.round(followers * formatReach * slotMult * pillarAff * noiseReach));
const erBase = fmt==='reel'?0.027:(fmt==='carousel'?0.014:0.013);
const engagement = Math.max(1, Math.round(reach * erBase * capMult * noiseEng));
const likes = Math.round(engagement*0.78);
const saves = Math.round(engagement*0.10);
const comments = Math.round(engagement*0.07);
const shares = Math.max(0, engagement - likes - saves - comments);
const video_views = fmt==='reel' ? Math.round(reach*1.1) : 0;
const wtr = fmt==='reel' ? Math.min(0.7, Math.max(0.1, 0.35 + 0.1*gauss())) : 0;
return {json:{
  post_id: r.post_id, batch_id: String(r.batch_id), format: fmt, pillar: r.pillar, slot_label: r.slot_label || (String(hour)+':00'),
  source: 'synthetic',
  reach: String(reach), likes: String(likes), comments: String(comments), saves: String(saves), shares: String(shares),
  video_views: String(video_views), watch_through_rate: fmt==='reel'?wtr.toFixed(3):'',
  engagement_total: String(engagement), er: (engagement/reach).toFixed(5),
  measured_at: 'sim-v1-deterministic'
}};

const resp = $json;
const orig = $('Mode?').item.json;
const get = name => { const m = (resp.data||[]).find(d=>d.name===name); return m && m.values && m.values[0] ? Number(m.values[0].value)||0 : 0; };
const reach = get('reach'), likes = get('likes'), comments = get('comments'), saves = get('saved'), shares = get('shares'), views = get('views');
const engagement = likes+comments+saves+shares;
let hour = 20; try { hour = DateTime.fromISO(String(orig.publish_at)).setZone('Africa/Cairo').hour; } catch(e) {}
return {json:{
  post_id: orig.post_id, batch_id: String(orig.batch_id), format: String(orig.format||'').toLowerCase(), pillar: orig.pillar, slot_label: orig.slot_label || (String(hour)+':00'),
  source: 'live',
  reach: String(reach), likes: String(likes), comments: String(comments), saves: String(saves), shares: String(shares),
  video_views: String(views), watch_through_rate: '',
  engagement_total: String(engagement), er: reach>0?(engagement/reach).toFixed(5):'0',
  measured_at: new Date().toISOString()
}};

const metrics = $input.all().map(i=>i.json);
const byBatch = {};
for (const m of metrics){ (byBatch[m.batch_id] = byBatch[m.batch_id]||[]).push(m); }
const mean = a => a.length ? a.reduce((s,x)=>s+x,0)/a.length : 0;
const agg = {};
for (const [b, arr] of Object.entries(byBatch)){
  const groupBy = key => { const o={}; for (const m of arr){ const k=m[key]||'?'; (o[k]=o[k]||[]).push(parseFloat(m.er)); } return Object.fromEntries(Object.entries(o).map(([k,v])=>[k, +(mean(v).toFixed(5))])); };
  const groupEng = key => { const o={}; for (const m of arr){ const k=m[key]||'?'; (o[k]=o[k]||[]).push(parseFloat(m.engagement_total)); } return Object.fromEntries(Object.entries(o).map(([k,v])=>[k, +(mean(v).toFixed(1))])); };
  agg[b] = {
    posts: arr.length,
    mean_er: +(mean(arr.map(m=>parseFloat(m.er))).toFixed(5)),
    mean_reach: Math.round(mean(arr.map(m=>parseFloat(m.reach)))),
    mean_engagement: +(mean(arr.map(m=>parseFloat(m.engagement_total))).toFixed(1)),
    er_by_format: groupBy('format'),
    er_by_pillar: groupBy('pillar'),
    er_by_slot: groupBy('slot_label'),
    engagement_by_format: groupEng('format'),
    engagement_by_pillar: groupEng('pillar'),
    engagement_by_slot: groupEng('slot_label'),
    posts_detail: arr.map(m=>({id:m.post_id, format:m.format, pillar:m.pillar, slot:m.slot_label, reach:+m.reach, engagement:+m.engagement_total, er:+m.er})),
    top: arr.slice().sort((x,y)=>parseFloat(y.er)-parseFloat(x.er)).slice(0,2).map(m=>({post_id:m.post_id, er:m.er, format:m.format, pillar:m.pillar, slot:m.slot_label})),
    bottom: arr.slice().sort((x,y)=>parseFloat(x.er)-parseFloat(y.er)).slice(0,2).map(m=>({post_id:m.post_id, er:m.er, format:m.format, pillar:m.pillar, slot:m.slot_label}))
  };
}
const batches = Object.keys(agg).map(Number).sort((x,y)=>x-y);
const latest = batches[batches.length-1];
return [{json:{ agg, batches, latest_batch: latest, next_batch: latest+1, metrics_count: metrics.length }}];

const out = $input.first().json.output;
const aggJ = $('Aggregate Stats').first().json;
const next = aggJ.next_batch;
return out.learnings.slice(0,5).map((l,i)=>({json:{
  learning_id: 'b' + next + '-' + String(l.dimension||'general').replace(/[^a-z_]/gi,'') + '-' + (i+1),
  batch_id: String(aggJ.latest_batch),
  created_at: new Date().toISOString(),
  insight_type: l.insight_type||'', dimension: l.dimension||'', directive: l.directive||'', evidence: l.evidence||'',
  applied_in_batch: String(next)
}}));

const aggJ = $('Aggregate Stats').first().json;
const agg = aggJ.agg;
const batches = aggJ.batches;
const cal = $('Read Calendar').all().map(i=>i.json).filter(r=>r.post_id && String(r.post_id).match(/^b\d+-p\d+$/));
const runlog = $('Read RunLog').all().map(i=>i.json).filter(r=>r.run_id);
const mean = a => a.length ? a.reduce((s,x)=>s+x,0)/a.length : 0;
const rows = [];
const now = new Date().toISOString();
for (const b of batches){
  const posts = cal.filter(r=>String(r.batch_id)===String(b));
  const nums = k => posts.map(p=>parseFloat(p[k])).filter(x=>!isNaN(x));
  rows.push({benchmark_id:'brand_consistency-b'+b, metric:'brand_consistency', value:+(mean(nums('judge_brand_score')).toFixed(2)), unit:'/5', batch_id:String(b), method:'mean of cross-model judge (gpt-4o-mini, temp 0, anchored rubric) final brand_consistency across batch', computed_at:now});
  rows.push({benchmark_id:'arabic_quality-b'+b, metric:'arabic_quality', value:+(mean(nums('judge_arabic_score')).toFixed(2)), unit:'/5', batch_id:String(b), method:'mean judge arabic_naturalness (anti-translationese rubric, native-Egyptian anchor)', computed_at:now});
  const lintPassed = posts.filter(p=>String(p.lint_pass)==='true').length;
  rows.push({benchmark_id:'lint_pass_rate-b'+b, metric:'lint_pass_rate', value: posts.length?+((lintPassed/posts.length)*100).toFixed(0):0, unit:'%', batch_id:String(b), method:'deterministic lint: always-tags present, 7-11 tags, no banned tags, caption lengths, bilingual presence', computed_at:now});
  const pre = nums('judge_brand_score_pre'), post = nums('judge_brand_score');
  if (pre.length) rows.push({benchmark_id:'judge_uplift_revision-b'+b, metric:'judge_score_uplift_from_revision', value:+(mean(post)-mean(pre)).toFixed(2), unit:'points/5', batch_id:String(b), method:'mean judge brand score after evaluator-optimizer revision minus before', computed_at:now});
  if (agg[b]) {
    rows.push({benchmark_id:'mean_er-b'+b, metric:'mean_engagement_rate', value:+((agg[b].mean_er)*100).toFixed(3), unit:'%', batch_id:String(b), method:'SYNTHETIC seeded simulator; ER = engagement/reach; constants from hospitality IG benchmarks', computed_at:now});
    rows.push({benchmark_id:'mean_engagement-b'+b, metric:'mean_engagement_per_post', value:agg[b].mean_engagement, unit:'actions/post', batch_id:String(b), method:'SYNTHETIC seeded simulator; likes+comments+saves+shares per post', computed_at:now});
    rows.push({benchmark_id:'mean_reach-b'+b, metric:'mean_reach_per_post', value:agg[b].mean_reach, unit:'accounts/post', batch_id:String(b), method:'SYNTHETIC seeded simulator', computed_at:now});
  }
  const rl = runlog.filter(r=>String(r.batch_id)===String(b) && r.workflow==='WF2-content-studio' && r.cost_per_post_usd);
  if (rl.length){
    const last = rl[rl.length-1];
    rows.push({benchmark_id:'cost_per_post-b'+b, metric:'cost_per_post', value:parseFloat(last.cost_per_post_usd)||0, unit:'USD', batch_id:String(b), method:'OpenRouter account usage delta across the WF2 run divided by posts approved', computed_at:now});
    if (last.duration_s && last.posts_count) rows.push({benchmark_id:'latency_per_post-b'+b, metric:'latency_per_post', value:+(parseFloat(last.duration_s)/parseFloat(last.posts_count)).toFixed(1), unit:'s (incl. approval wait)', batch_id:String(b), method:'WF2 wall-clock duration / posts in batch; includes human approval wait time', computed_at:now});
  }
}
if (batches.length>=2){
  const a = agg[batches[batches.length-2]], b2 = agg[batches[batches.length-1]];
  const span = 'b'+batches[batches.length-2]+'-to-b'+batches[batches.length-1];
  if (a && b2 && a.mean_engagement>0) rows.push({benchmark_id:'optimization_uplift-'+span, metric:'optimization_uplift_engagement', value:+(((b2.mean_engagement-a.mean_engagement)/a.mean_engagement)*100).toFixed(1), unit:'%', batch_id:batches.slice(-2).join('->'), method:'PRIMARY target metric: (mean engagement actions per post after - before) / before, on the seeded synthetic simulator. Slot/pillar directives grow audience reached, so engagement per post (reach x rate) is the honest lever; validates loop mechanics, not real IG performance', computed_at:now});
  if (a && b2 && a.mean_reach>0) rows.push({benchmark_id:'reach_uplift-'+span, metric:'optimization_uplift_reach', value:+(((b2.mean_reach-a.mean_reach)/a.mean_reach)*100).toFixed(1), unit:'%', batch_id:batches.slice(-2).join('->'), method:'secondary: mean simulated reach per post, before vs after', computed_at:now});
  if (a && b2 && a.mean_er>0) rows.push({benchmark_id:'er_uplift-'+span, metric:'optimization_uplift_er', value:+(((b2.mean_er-a.mean_er)/a.mean_er)*100).toFixed(1), unit:'%', batch_id:batches.slice(-2).join('->'), method:'secondary: mean ER before vs after; with a fixed weekly format quota ER moves little by design - reported for completeness', computed_at:now});
}
return rows.map(r=>({json:r}));

const init = $('Init Run').first().json;
const aggJ = $('Aggregate Stats').first().json;
const finished = new Date().toISOString();
return [{json:{
  run_id: init.run_id, workflow:'WF4-analyst', batch_id: String(aggJ.latest_batch),
  started_at: init.started_at, finished_at: finished,
  duration_s: String(Math.round((new Date(finished).getTime()-new Date(init.started_at).getTime())/1000)),
  llm_cost_usd:'', posts_count: String(aggJ.metrics_count), cost_per_post_usd:'',
  notes: 'metrics + learnings + benchmarks computed for batches ' + aggJ.batches.join(',')
}}];
